function decodeFields(text) {
  const fields = [];
  let current = '';

  for (let i = 0; i < text.length; i += 1) {
    const char = text[i];

    if (char === '|') {
      fields.push(current);
      current = '';
    } else if (char === '\\') {
      if (i + 1 >= text.length) {
        current += '\\';
        continue;
      }

      const escaped = text[i + 1];
      if (escaped !== '|' && escaped !== '\\') {
        throw new SyntaxError('Invalid escape sequence');
      }

      current += escaped;
      i += 1;
    } else {
